    test('create a configuration project', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)

        const factory = new ProjectFactory(fs as FileSystem, telemetry)

        const project = await factory.createConfigurationProject(
            '/',
            new MockConnector({
                getScopeInfo: jest.fn(async (scope, scopeId) => {
                    return {
                        name: 'TestApp',
                        appId: scopeId,
                        sysClassName: 'sys_store_app',
                        active: true,
                        scope: scope,
                        shortDescription: 'description',
                    }
                }),
            }),
            {
                scope: 'x_test',
                scopeId: '12345678901234567890123456789012',
            },
            {
                sdkVersion: '4.0.0',
            }
        )

        expect(telemetry.startTimerEvent).not.toHaveBeenCalled()
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(project).toBeDefined()

        const fsJson = Object.keys(vol.toJSON())
        expect(fsJson.includes('/now.config.json')).toBe(true)
        expect(fsJson.includes('/package.json')).toBe(true)
        expect(fsJson.includes('/.gitignore')).toBe(true)
        expect(fsJson.includes('/.eslintrc')).toBe(true)
        expect(fsJson.includes('/.vscode/extensions.json')).toBe(true)

        expect(fs.readFileSync('/now.config.json', 'utf-8')).toContain('"type": "configuration"')

        const packageJson = JSON.parse(fs.readFileSync('/package.json', 'utf-8') as string)
        expect(packageJson).toHaveProperty('name', 'x_test-configuration')
        expect(packageJson).toHaveProperty('version', '0.0.1')
    })
